 */
scwin.init = function() {
    txb_DISCLS_TITLE.setValue(scwin.gDisclsTitle);
    txb_COM_NM.setValue(scwin.gComNm);
    txb_FS_ACNT_TP_NM.setValue(scwin.gFsAcntTpNm);
