 * @description list Cd Sync 처리
 * @returns {void}
 * @hidden N
 */
scwin.listCdSync = function() {
    const limit = 3;
    for (let i = 1; i <= limit; i++) {
        eval("fn_Search_n(" + i + ")"); // 1_재무상태표, 2_손익계산서, 3_자본변동표

        if (i < limit) eval("fn_Search_Xbrl_n(" + i + ")"); // 자본변동표는 수정불가

    }
};

/**
 * @method
 * @name checkNum
 * @description check Num 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} data 데이터
 * @param {*} text text
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkNum = async function(row, colid, data, text) {
    let num = $p.getComponentById("dts_" + text).getCellData(row, colid);
    // ex) (1,632,712,242) 일시 음수로 본다.
    if (num.indexOf('(') > -1) {
        num = '-' + num;
    }
    num = num.replace(/\,|\(|\)/g, '');
    num = num.replace(/\s/g, '');
    eval("dts_" + text, num).setCellData(row, colid);
    if (isNaN($p.getComponentById("dts_" + text).getCellData(row, colid))) {
        await $c.win.alert("올바른 숫자형식으로 값을 입력해주세요.");
        // eval("dts_" + text).NameValue(row,colid) = "123";
        $p.getComponentById("grd_" + text).Focus();
    }
};

/**
 * @method
 * @name isDate
 * @description is Date 처리
 * @param {*} dd dd
 * @returns {void}
 * @hidden N
 */
scwin.isDate = function(dd) {
    try {
        let y, m, d = "";
        if (dd.length !== 8) {
            return false;
        } else {
            y = dd.substr(0, 4);
            m = dd.substr(4, 2);
            d = dd.substr(6, 2);
        }
        const date = new Date(y, m - 1, d);
        if (y === date.getFullYear() && m - 1 === date.getMonth() && d === date.getDate()) {
            return date;
        } else {
            return false;
        }
    } catch (e) {
        return false;
    }
};

/**
 * @method
 * @name validCheck
 * @description 숫자 확인_재무상태표
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validCheck = async function() {
    // 숫자 확인_재무상태표
    for (let i = 1; i <= dts_1_1.getRowCount(); i++) {
        dts_1_1.setRowPosition(i, 0);
        for (let a = 1; a < 3; a++) {
            let num = dts_1_1.getCellData(i, "text_1_" + a);
            if (!$c.ut.isNum(num < 0 ? num * (-1) : num)) {
                MaxTab_01.setSelectedTabIndex("1"); // 탭이동
                await $c.win.alert("숫자를 입력해 주세요.");
                grd_1_1.SetColumn("text_1_" + a);
                grd_1_1.focus();
                return false;
            }
        }
    }
    // 숫자 확인_손익계산서
    for (let i = 1; i <= dts_2_1.getRowCount(); i++) {
        dts_2_1.setRowPosition(i, 0);
        for (let a = 1; a < 5; a++) {
            let num = dts_2_1.getCellData(i, "text_2_" + a);
            if (!$c.ut.isNum(num < 0 ? num * (-1) : num)) {
                MaxTab_01.setSelectedTabIndex("2"); // 탭이동
                await $c.win.alert("숫자를 입력해 주세요.");
                grd_2_1.SetColumn("text_2_" + a);
                grd_2_1.focus();
                return false;
            }
        }
    }

    // 입력여부 확인_재무상태표
    for (let i = 1; i <= dts_1_1.getRowCount(); i++) {
        dts_1_1.setRowPosition(i, 0);
        for (let a = 0; a < 3; a++) {
            if (dts_1_1.getCellData(i, "text_1_" + a) === "") {
                MaxTab_01.setSelectedTabIndex("1"); // 탭이동
                await $c.win.alert("입력되지 않은 항목이 있습니다.");
                grd_1_1.SetColumn("text_1_" + a);
                grd_1_1.focus();
                return true;
            }
        }
    }
    // 입력여부 확인_손익계산서
    for (let i = 1; i <= dts_2_1.getRowCount(); i++) {
        dts_2_1.setRowPosition(i, 0);
        for (let a = 0; a < 5; a++) {
            if (dts_2_1.getCellData(i, "text_2_" + a) === "") {
                MaxTab_01.setSelectedTabIndex("2"); // 탭이동
                await $c.win.alert("입력되지 않은 항목이 있습니다.");
                grd_2_1.SetColumn("text_2_" + a);
                grd_2_1.focus();
                return true;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name save
 * @description 등록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // 등록
    if (!await scwin.validCheck()) {
        return;
    }
    if (confirm('저장 하시겠습니까?')) {
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/IfrsDisclosureStatistics.do",
            ref : "dts_1_1,dts_2_1",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

