    if (confirm(str)) {

        // dts_delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_delete.insertRow();
        dts_delete.setCellData(1, "EMP_NO", js_emp_no);
        trs_Delete.Action = "/IfrsDisclosureStatistics.do?method=deleteIfrsWrtrptInfo&ACPT_NO=" + scwin.gAcptNo + "&FS_ACNT_TP_CD=" + scwin.gFsAcntTpCd + "&SCREN_ID=" + 'ULDSTF26316.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Delete.KeyValue = "JSP(I:pInput1=dts_delete)";
        trs_Delete.post();
    }
};

/**
