/**
 * @method
 * @name setPosition
 * @description set Position 처리
 * @returns {void}
 * @hidden N
 */
scwin.setPosition = function() {
    if (document.getElementById("ifrCtrl") !== null && document.getElementById("ifrCtrl").readyState === 'complete') {
        // 로딩이 완료되면
        clearInterval(scwin.gInterval);

        // 탭 활성화
        MaxTab_01.setDisabled(true);

        // tab 클릭 시 위치 이동되도록 id 설정
        scwin.setElementId();
        scwin.movePosition(MaxTab_01.getSelectedTabIndex());
    }
};

/**
 * @method
 * @name movePosition
 * @description move Position 처리
 * @param {*} to to
 * @returns {void}
 * @hidden N
 */
scwin.movePosition = function(to) {
    let temp = ifrCtrl.location.href;
    if (temp.indexOf("#pos") > -1) {
        temp = temp.substring(0, temp.indexOf("#pos"));
    }
    ifrCtrl.location.href = temp + "#pos_1000" + to;
};

/**
 * @method
 * @name setElementId
 * @description set Element Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.setElementId = function() {
    const bodyFrame = document.getElementById("ifrCtrl").contentWindow.document;
    const classArr = document.getElementsByClassName("nb", bodyFrame);
    let isExistPTag = false;

    // pTag유무 확인
    for (let i = classArr.length - 1; i >= 0; i--) {
        if (typeof(classArr[i].getElementsByTagName('p')[0]) !== "undefined") {
            if ($c.ut.replaceAll(classArr[i].getElementsByTagName('p')[0].innerText, " ", "").indexOf("재무상태표") > -1) {
                isExistPTag = true;
                i = -1;
            }
        }
    }

    // id 설정
    for (let i = classArr.length - 1; i >= 0; i--) {
        // 정정보고서 때문에 검색방향 변경
        let pTagArr = null;
        // p 태그가 없는 경우엔 클래스 TD를 확인
        if (isExistPTag) pTagArr = classArr[i].getElementsByTagName('p');

        else pTagArr = document.getElementsByClassName("TD", classArr[i]);
        if (typeof(pTagArr[0]) !== "undefined") {
            if (scwin.gFsAcntTpCd === "2") {
                // 개별
                if ($c.ut.replaceAll(pTagArr[0].innerText, " ", "").indexOf("재무상태표") > -1 && $c.ut.replaceAll(pTagArr[0].innerText, " ", "").indexOf("연결") < 0) {
                    pTagArr[0].innerHTML = "<span id='pos_10001'>" + pTagArr[0].innerText + "</span>";
                    i = -1;
                } else if ($c.ut.replaceAll(pTagArr[0].innerText, " ", "").indexOf("손익계산서") > -1 && $c.ut.replaceAll(pTagArr[0].innerText, " ", "").indexOf("연결") < 0) {
                    pTagArr[0].innerHTML = "<span id='pos_10002'>" + pTagArr[0].innerText + "</span>";
                } else if ($c.ut.replaceAll(pTagArr[0].innerText, " ", "").indexOf("자본변동표") > -1 && $c.ut.replaceAll(pTagArr[0].innerText, " ", "").indexOf("연결") < 0) {
                    pTagArr[0].innerHTML = "<span id='pos_10003'>" + pTagArr[0].innerText + "</span>";
                } else if ($c.ut.replaceAll(pTagArr[0].innerText, " ", "").indexOf("현금흐름표") > -1 && $c.ut.replaceAll(pTagArr[0].innerText, " ", "").indexOf("연결") < 0) {
                    pTagArr[0].innerHTML = "<span id='pos_10004'>" + pTagArr[0].innerText + "</span>";
                }
            } else if (scwin.gFsAcntTpCd === "1") {
                // 연결
                if ($c.ut.replaceAll(pTagArr[0].innerText, " ", "").indexOf("연결재무상태표") > -1) {
                    pTagArr[0].innerHTML = "<span id='pos_10001'>" + pTagArr[0].innerText + "</span>";
                    i = -1;
                } else if ($c.ut.replaceAll(pTagArr[0].innerText, " ", "").indexOf("연결") > -1 && $c.ut.replaceAll(pTagArr[0].innerText, " ", "").indexOf("손익계산서") > -1) {
                    pTagArr[0].innerHTML = "<span id='pos_10002'>" + pTagArr[0].innerText + "</span>";
                } else if ($c.ut.replaceAll(pTagArr[0].innerText, " ", "").indexOf("연결자본변동표") > -1) {
                    pTagArr[0].innerHTML = "<span id='pos_10003'>" + pTagArr[0].innerText + "</span>";
                } else if ($c.ut.replaceAll(pTagArr[0].innerText, " ", "").indexOf("연결현금흐름표") > -1) {
                    pTagArr[0].innerHTML = "<span id='pos_10004'>" + pTagArr[0].innerText + "</span>";
                }
            }
        }
    }
};

// getElementsByClassName 사용이 안됨.. 버전문제인듯..
if (!document.getElementsByClassName) {
    document.getElementsByClassName = function(className, element) {
        // var children = (element || document).getElementsByTagName('*');
        const children = element.getElementsByTagName('*');
        const elements = new Array();
        for (let i = 0; i < children.length; i++) {
            const child = children[i];
            const classNames = child.className.split(' ');
            for (let j = 0; j < classNames.length; j++) {
                if (classNames[j] === className) {
                    elements.push(child);
                    break;
                }
            }
        }
        return elements;
    };
}

