 * @method
 * @name grd_1_2_OnDblClick
 * @description grd_1_2 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_1_2_OnDblClick = function(row, colid) {
    if (colid === 'text_1_3') {
        let line = dts_1_2.getCellData(row, "LINE");
        dts_1_1.setRowPosition(line, 0);
        let col_0 = dts_1_2.getCellData(row, "text_1_0");
        let col_1 = dts_1_2.getCellData(row, "text_1_1");
        let col_2 = dts_1_2.getCellData(row, "text_1_2");
        let msg = col_0 + " : " + col_1 + ", " + col_2 + "\n\n적용하시겠습니까?";

        // grd_1_1의 같은 자리에 데이터 복사
        if (confirm(msg)) {
            dts_1_1.setCellData(line, "text_1_1", col_1);
            dts_1_1.setCellData(line, "text_1_2", col_2);
        }
    }
};

/**
 * @method
 * @name grd_2_2_OnDblClick
 * @description grd_2_2 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_2_2_OnDblClick = function(row, colid) {
    if (colid === 'text_2_5') {
        let line = dts_2_2.getCellData(row, "LINE");
        dts_2_1.setRowPosition(dts_2_2.getCellData(row, "LINE"), 0);
        let col_0 = dts_2_2.getCellData(row, "text_2_0");
        let col_1 = dts_2_2.getCellData(row, "text_2_1");
        let col_2 = dts_2_2.getCellData(row, "text_2_2");
        const col_3 = dts_2_2.getCellData(row, "text_2_3");
        const col_4 = dts_2_2.getCellData(row, "text_2_4");
        let msg = col_0 + " : " + col_1 + ", " + col_2 + ", " + col_3 + ", " + col_4 + "\n\n적용하시겠습니까?";

        // grd_2_1의 같은 자리에 데이터 복사
        if (confirm(msg)) {
            dts_2_1.setCellData(line, "text_2_1", col_1);
            dts_2_1.setCellData(line, "text_2_2", col_2);
            dts_2_1.setCellData(line, "text_2_3", col_3);
            dts_2_1.setCellData(line, "text_2_4", col_4);
        }
    }
};

