/**
 * @method
 * @name dts_AcptProcs_OnLoadCompleted
 * @description dts_AcptProcs 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_AcptProcs_OnLoadCompleted = async function(rowcount) {
    const vDocNo = dts_AcptProcs.getCellData(1, "DISCLS_DOC_NO");
    const sMainFormCd = dts_AcptProcs.getCellData(1, "FORM_CD");
    const sFormVer = dts_AcptProcs.getCellData(1, "FORM_VER");
    const sLangTpCd = dts_AcptProcs.getCellData(1, "LANG_TP_CD");
    scwin.gSubmitSysTp = dts_AcptProcs.getCellData(1, "SUBMIT_SYS_TP_CD"); // 제출구문 - 한글자동변환 :0=국문제출, 1=영문제출
    scwin.gProcs_063 = dts_AcptProcs.getCellData(1, "FPROCS_063"); // 시장조치관련 - 영문자동변환대상 : count(*)

    if (scwin.gSubmitSysTp === '0' && sLangTpCd === '1') {
        // 국문제출에서 제출한 영문공시를 디폴트로 볼때..
        await scwin.getDocHtmlURL(vDocNo, sMainFormCd, sFormVer, '0', scwin.gSubmitSysTp);
    } else {
        await scwin.getDocHtmlURL(vDocNo, sMainFormCd, sFormVer, sLangTpCd, scwin.gSubmitSysTp);
    }
};

/**
 * @method
 * @name dts_DocUrl_OnLoadCompleted
